const MOD = 998244353;

const MAX_N = 10000; // sufficient for n up to ~5000+100

const fact = new Array(MAX_N + 1);
const invFact = new Array(MAX_N + 1);
const inv = new Array(MAX_N + 1);

fact[0] = 1;
for (let i = 1; i <= MAX_N; i++) fact[i] = fact[i - 1] * i % MOD;

invFact[MAX_N] = modPow(fact[MAX_N], MOD - 2);
for (let i = MAX_N; i >= 1; i--) invFact[i - 1] = invFact[i] * i % MOD;

for (let i = 1; i <= MAX_N; i++) inv[i] = modPow(i, MOD - 2);

function modPow(a, e) {
    let r = 1;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

function C(n, k) {
    if (n < 0 || k < 0 || k > n) return 0;
    return fact[n] * invFact[k] % MOD * invFact[n - k] % MOD;
}

// Number of ways to write sum 's' as sum of 'n' non-negative integers each < 'upperBound'
// i.e., 0 <= x_i < upperBound
function waysBounded(s, n, upperBound) {
    if (s < 0) return 0;
    if (upperBound <= 0) {
        return s === 0 ? 1 : 0;
    }
    let res = 0;
    // Inclusion-Exclusion: sum_{k=0..n} (-1)^k * C(n, k) * C(s - k*upperBound + n - 1, n - 1)
    // Max k such that s - k*upperBound >= 0
    const maxK = Math.min(n, Math.floor(s / upperBound));
    for (let k = 0; k <= maxK; k++) {
        const rem = s - k * upperBound;
        const term = C(n, k) * C(rem + n - 1, n - 1) % MOD;
        if (k % 2 === 0) {
            res = (res + term) % MOD;
        } else {
            res = (res - term + MOD) % MOD;
        }
    }
    return res;
}

function solve() {
    const input = require('fs').readFileSync('/dev/stdin', 'utf8').trim().split(/\s+/).map(Number);
    const p = input[0];
    const s = input[1];
    const r = input[2];

    // Total number of states: a1 >= r, sum = s.
    // Let a1' = a1 - r >= 0. Sum of a1' + a2 + ... + ap = s - r.
    // Number of solutions = C(s - r + p - 1, p - 1)
    const totalStates = C(s - r + p - 1, p - 1);

    let winningProb = 0;

    // Iterate over Hasan's actual score x
    for (let x = r; x <= s; x++) {
        const remSum = s - x;
        // Number of ways for other p-1 players to sum to remSum with each score < x
        // This ensures Hasan is the unique winner.
        const waysUniqueWin = waysBounded(remSum, p - 1, x);

        // Number of ways for other p-1 players to sum to remSum with each score <= x
        // This includes cases where max score is x (ties possible).
        const waysMaxAtMostX = waysBounded(remSum, p - 1, x + 1);

        // Number of ways with ties at x = waysMaxAtMostX - waysUniqueWin
        const waysTie = (waysMaxAtMostX - waysUniqueWin + MOD) % MOD;

        // Probability contribution:
        // Unique win: 1 * waysUniqueWin
        // Tie: 1/(k+1) where k is number of other players with score x.
        // We need sum over all tie states of 1/(number_of_top_scorers).
        // Instead of iterating k, we can use combinatorial identity or iterate k.
        // For a specific x, we sum over k=1..p-1: ways where exactly k others have score x, and rest < x.
        // Contribution = sum_k C(p-1, k) * waysBounded(remSum - k*x, p-1-k, x) * inv[k+1]
        let tieContribution = 0;
        if (x > 0) { // If x=0, ties at 0, but bound is <0 impossible unless remSum=0. Handled by waysBounded returning 0 for upperBound<=0 unless sum=0.
            // Max k such that k*x <= remSum
            const maxK = Math.min(p - 1, Math.floor(remSum / x));
            for (let k = 1; k <= maxK; k++) {
                const rem = remSum - k * x;
                // Choose which k players have score x
                // Remaining p-1-k players have score in [0, x-1] summing to rem
                const ways = C(p - 1, k) * waysBounded(rem, p - 1 - k, x) % MOD;
                tieContribution = (tieContribution + ways * inv[k + 1]) % MOD;
            }
        }

        const totalWaysForX = (waysUniqueWin + tieContribution) % MOD;
        winningProb = (winningProb + totalWaysForX) % MOD;
    }

    // Result = winningProb / totalStates mod MOD
    const invTotal = modPow(totalStates, MOD - 2);
    const ans = winningProb * invTotal % MOD;
    console.log(ans);
}

solve();
